from pathlib import Path
import re

MAIN=Path('web/src/main.js')
CSS=Path('web/src/styles.css')
PKG=Path('web/package.json')
s=MAIN.read_text(encoding='utf-8')


def sub1(pattern,repl,label):
    global s
    s2,n=re.subn(pattern,repl,s,count=1,flags=re.S)
    if n!=1: raise SystemExit(f'{label}: expected 1 match, got {n}')
    s=s2

# State: cache recent player news.
s=s.replace("profile:null,profileRoster:null,games:[]","profile:null,profileRoster:null,playerNews:new Map,games:[]",1)

# Fresh player metadata: 15-minute cache, manual Refresh forces a Sleeper refresh.
sub1(r"async function players\(\)\{.*?\}\nfunction pname",
"""async function players(force=false){if(st.players&&!force)return;try{const c=localStorage.fm_players_cache,t=+localStorage.fm_players_cache_at;if(!force&&c&&Date.now()-t<15*60*1000){st.players=JSON.parse(c);return}}catch{}const fresh=await liveJson(`${S}/players/nfl`,null);if(fresh&&Object.keys(fresh).length)st.players=fresh;else if(!st.players)st.players={};try{if(st.players&&Object.keys(st.players).length){localStorage.fm_players_cache=JSON.stringify(st.players);localStorage.fm_players_cache_at=Date.now()}}catch{}}\nfunction pname""",
'players cache')

# Availability-aware model output. Current-week IR/Out/etc is a hard 0. The existing
# model availability_factor remains authoritative for softer/future risk.
sub1(r"function model\(id,p=st\.players\?\.\[id\],week=st\.week\)\{.*?\}\nfunction auditProjections",
"""function model(id,p=st.players?.[id],week=st.week){if(isDstId(id,p))return dstModel(id,p,week);const e=resolveModel(id,p),base=e?.base||null,w=e?.weeks?.get(+week)||null,current=+st.snapshot?.projection_week===+week,avgInfo=seasonPpgInfo(id,p,e);const weekField=keys=>field(w,keys)??(current?field(base,keys):null),snapshotFactor=n(field(w,['availability_factor']),1),availability=availabilityInfo(id,p,week,snapshotFactor),snapshotProjection=n(weekField(['live_projection','current_projection','projected_points','projection','proj_fpts','fpts_proj','pred','prediction','mean','weekly_projection'])),snapshotFloor=n(weekField(['floor','projection_floor','p10','lower','lower_bound'])),snapshotCeiling=n(weekField(['ceiling','projection_ceiling','p90','upper','upper_bound'])),rawProjection=snapshotProjection!=null&&snapshotFactor>0?snapshotProjection/snapshotFactor:snapshotProjection;return{projection:availability.forceZero?0:snapshotProjection,rawProjection,pregame:n(weekField(['pregame_projection','original_projection','base_projection','neutral_projection','projected_points','projection'])),floor:availability.forceZero?0:snapshotFloor,ceiling:availability.forceZero?0:snapshotCeiling,avg:avgInfo.value,avgSource:avgInfo.source,avgGames:avgInfo.games,dynasty:n(field(base,['dynasty_value','dynasty','asset_value','value','dynasty_score'])??field(w,['dynasty_value','dynasty','asset_value','value','dynasty_score'])),confidence:availability.forceZero?'Out':weekField(['confidence','projection_confidence','conf','confidence_score']),opp:weekField(['opponent','opp','opponent_team','opp_team']),availabilityFactor:availability.factor,availability,projectionWasOverridden:availability.forceZero&&snapshotProjection!=null&&snapshotProjection!==0,matched:!!e,hasWeek:!!w}}\nfunction auditProjections""",
'model availability overlay')

# Add injury/news helpers after seasonStat.
anchor="function seasonStat(id,key,aliases=[]){const x=dstStats(st.seasonStats.get(String(id)));return n(field(x,[key,...aliases]))}"
if anchor not in s: raise SystemExit('seasonStat anchor missing')
helpers=r'''function seasonStat(id,key,aliases=[]){const x=dstStats(st.seasonStats.get(String(id)));return n(field(x,[key,...aliases]))}
function availabilityInfo(id,p=st.players?.[id],week=st.week,snapshotFactor=1){const rosterStatus=String(p?.status||'').trim(),injuryStatus=String(p?.injury_status||'').trim(),body=String(p?.injury_body_part||'').trim(),notes=String(p?.injury_notes||'').trim(),rs=rosterStatus.toLowerCase(),is=injuryStatus.toLowerCase(),hardRoster=/(^|\b)(ir|pup|nfi|sus)($|\b)|injured reserve|physically unable|non.?football injury|suspended/.test(rs),hardInjury=/^out$/.test(is),current=+week===+st.nflWeek,snapshotZero=n(snapshotFactor,1)<=0,forceZero=snapshotZero||(current&&(hardRoster||hardInjury)),factor=forceZero?0:Math.max(0,Math.min(1,n(snapshotFactor,1))),label=injuryStatus||(!/^active$/i.test(rosterStatus)?rosterStatus:'')||'',reason=snapshotZero?'Fantasy Model availability factor is 0 for this player-week.':current&&hardRoster?`${rosterStatus||'Unavailable'} from fresh Sleeper roster status.`:current&&hardInjury?`Sleeper lists the player Out for the current NFL week.`:factor<1?`Fantasy Model availability factor ${Math.round(factor*100)}% is already applied to the weekly forecast.`:label?`${label} is being monitored; no additional numeric override is applied unless availability becomes definitive.`:'No current availability restriction detected.';return{factor,forceZero,label,rosterStatus,injuryStatus,body,notes,reason,currentWeek:current}}
function availabilityChip(a){if(!a||(!a.label&&a.factor>=1))return'';const tone=a.factor<=0?'bad':a.factor<1||/question|doubt/i.test(a.label)?'warn':'neutral',txt=[a.label,a.body].filter(Boolean).join(' · ');return`<span class="availability-chip ${tone}">${esc(txt||`Availability ${Math.round(a.factor*100)}%`)}</span>`}
function newsDate(v){if(!v)return'';const d=new Date(v);return Number.isNaN(d.getTime())?'':d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:d.getFullYear()!==new Date().getFullYear()?'numeric':undefined})}
async function loadPlayerNews(id,force=false){const key=String(id),cached=st.playerNews.get(key);if(!force&&cached&&Date.now()-n(cached.at,0)<10*60*1000)return cached;const p=st.players?.[id]||{},espnId=p?.espn_id;if(!espnId){const z={at:Date.now(),articles:[],source:'ESPN',unavailable:true};st.playerNews.set(key,z);return z}st.playerNews.set(key,{at:Date.now(),loading:true,articles:[],source:'ESPN'});if(String(st.profile)===key)render();const data=await liveJson(`https://site.api.espn.com/apis/site/v2/sports/football/nfl/athletes/${encodeURIComponent(espnId)}/news?limit=6`,null),articles=Array.isArray(data?.articles)?data.articles.slice(0,6).map(a=>({headline:a?.headline||a?.title||'Player update',description:a?.description||a?.story||'',published:a?.published||a?.lastModified||'',url:a?.links?.web?.href||a?.link?.href||''})):[];const z={at:Date.now(),articles,source:'ESPN',unavailable:!data};st.playerNews.set(key,z);if(String(st.profile)===key)render();return z}
function openPlayerProfile(id,roster=null){st.profile=String(id);st.profileRoster=roster||null;render();loadPlayerNews(id)}
'''
s=s.replace(anchor,helpers,1)

# Explain availability in the generated analysis.
sub1(r"function profileAnalysis\(id,p,m\)\{.*?\}\nfunction playerProfile",
"""function profileAnalysis(id,p,m){const notes=[];if(m.availability?.factor<=0){notes.push(`Availability override: ${m.availability.reason} The displayed Week ${st.week} projection is therefore 0.0.`)}else if(m.availability?.factor<1){notes.push(`Availability is reducing this week's statistical forecast to ${Math.round(m.availability.factor*100)}% of the pre-availability baseline.`)}if(m.projection!=null&&m.avg!=null&&m.availability?.factor>0){const d=m.projection-m.avg,a=Math.abs(d);notes.push(a<0.75?`Week ${st.week} projects very close to the current-season scoring rate.`:`Week ${st.week} projects ${f(a)} points ${d>0?'above':'below'} the current-season scoring rate.`)}if(m.floor!=null&&m.ceiling!=null&&m.availability?.factor>0){const span=m.ceiling-m.floor;notes.push(span>=10?`The ${f(m.floor)}–${f(m.ceiling)} range is relatively wide, so this profile carries meaningful weekly volatility.`:`The ${f(m.floor)}–${f(m.ceiling)} range is relatively compact, giving this projection a steadier weekly shape.`)}const e=resolveModel(id,p),rank=n(field(e?.base,['dynasty_rank','model_dynasty_rank','overall_dynasty_rank']));if(m.dynasty!=null)notes.push(rank!=null?`Long-term model value is ${fi(m.dynasty)} with a dynasty rank of #${fi(rank)}.`:`Long-term model value is ${fi(m.dynasty)} on the site's player/pick currency.`);return notes}\nfunction playerProfile""",
'profile analysis')

# Replace player profile with availability + news sections while preserving current metrics.
sub1(r"function playerProfile\(\)\{.*?\}\n\nfunction dstProjectionValue",
r'''function playerProfile(){const id=st.profile;if(!id)return'';const p=st.players?.[id]||{},dst=isDstId(id,p),m=model(id,p),e=resolveModel(id,p),b=e?.base||{},rank=n(field(b,['dynasty_rank','model_dynasty_rank','overall_dynasty_rank'])),y3=n(field(b,['year3_fppg'])),career=n(field(b,['dynasty_career_projected_points','career_projected_points'])),ageV=n(p?.age??field(b,['age'])),gp=m.avgGames,avgSub=m.avgSource==='actual'?`Actual · ${gp||0} GP`:m.avgSource==='projected'?'Projected baseline':'Unavailable',pos=String(p?.position||field(b,['position'])||'').toUpperCase(),stats=[];if(pos==='QB'){stats.push(['Pass Att',seasonStat(id,'pass_att')],['Pass Yds',seasonStat(id,'pass_yd',['pass_yds'])],['Pass TD',seasonStat(id,'pass_td')],['Rush Att',seasonStat(id,'rush_att')])}else if(pos==='RB'){stats.push(['Carries',seasonStat(id,'rush_att')],['Rush Yds',seasonStat(id,'rush_yd',['rush_yds'])],['Targets',seasonStat(id,'rec_tgt',['targets'])],['Receptions',seasonStat(id,'rec')])}else if(['WR','TE'].includes(pos)){stats.push(['Targets',seasonStat(id,'rec_tgt',['targets'])],['Receptions',seasonStat(id,'rec')],['Rec Yds',seasonStat(id,'rec_yd',['rec_yds'])],['Rec TD',seasonStat(id,'rec_td')])}const notes=profileAnalysis(id,p,m),av=m.availability||availabilityInfo(id,p,st.week,1),news=st.playerNews.get(String(id)),projectionSub=m.projectionWasOverridden&&m.rawProjection!=null?`Availability override · base ${f(m.rawProjection)}`:av.factor<1?`Availability ${Math.round(av.factor*100)}% applied`:'Model projection',newsHtml=news?.loading?'<div class="news-loading">Loading recent player reports…</div>':news?.articles?.length?news.articles.map(a=>`<a class="news-card" ${a.url?`href="${esc(a.url)}" target="_blank" rel="noopener"`:''}><div class="news-meta">${esc(newsDate(a.published))}${news.source?` · ${esc(news.source)}`:''}</div><strong>${esc(a.headline)}</strong>${a.description?`<p>${esc(String(a.description).slice(0,220))}${String(a.description).length>220?'…':''}</p>`:''}</a>`).join(''):'<div class="muted small">No recent player-specific reports were returned for this player.</div>';return`<div class="profile-backdrop" data-profile-backdrop><aside class="player-profile" role="dialog" aria-modal="true" aria-label="${esc(pname(id))} player profile"><div class="profile-grabber"></div><div class="profile-head"><img class="profile-image ${dst?'dst-logo':''}" src="${assetImage(id,p)}" alt="" onerror="this.style.visibility='hidden'"><div class="profile-title"><div class="eyebrow">Player card</div><h2>${esc(pname(id))}</h2><div class="player-meta">${esc(pos||'—')} · ${esc(p?.team||field(b,['team'])||'FA')}${ageV!=null?` · Age ${f(ageV,0)}`:''}</div><div class="player-opp">${esc(m.opp||'Matchup unavailable')}</div>${availabilityChip(av)}</div><button class="profile-close" data-a="closeProfile" aria-label="Close player profile">×</button></div><div class="profile-metrics"><div class="profile-metric ${av.factor<=0?'availability-zero':''}"><span>Week ${st.week}</span><strong>${f(m.projection)}</strong><small>${esc(projectionSub)}</small></div><div class="profile-metric"><span>Season PPG</span><strong>${f(m.avg)}</strong><small>${esc(avgSub)}</small></div><div class="profile-metric"><span>Range</span><strong>${f(m.floor)}–${f(m.ceiling)}</strong><small>Floor–ceiling</small></div><div class="profile-metric"><span>Dynasty</span><strong>${m.dynasty!=null?fi(m.dynasty):'—'}</strong><small>${rank!=null?`Rank #${fi(rank)}`:'Model value'}</small></div></div>${(av.label||av.factor<1||av.body||av.notes)?`<div class="availability-panel ${av.factor<=0?'bad':av.factor<1?'warn':''}"><div><span>Availability</span><strong>${esc(av.label||`${Math.round(av.factor*100)}% available`)}</strong></div>${av.body?`<div><span>Injury</span><strong>${esc(av.body)}</strong></div>`:''}<p>${esc(av.reason)}</p>${av.notes?`<small>${esc(av.notes)}</small>`:''}</div>`:''}${stats.some(([,v])=>v!=null)?`<div class="profile-section"><div class="profile-section-title">Current season production</div><div class="profile-stat-grid">${stats.map(([k,v])=>`<div><span>${k}</span><strong>${v==null?'—':f(v,0)}</strong></div>`).join('')}</div></div>`:''}<div class="profile-section"><div class="profile-section-title">Model context</div><div class="profile-context-grid"><div><span>Confidence</span><strong>${esc(conf(m.confidence))}</strong></div><div><span>Availability</span><strong>${Math.round(av.factor*100)}%</strong></div><div><span>Year 3 PPG</span><strong>${f(y3)}</strong></div><div><span>Career projected pts</span><strong>${career!=null?fi(career):'—'}</strong></div></div></div><div class="profile-section"><div class="profile-section-title">Why this projection</div><div class="analysis-list">${notes.length?notes.map(x=>`<div class="analysis-item"><span>•</span><p>${esc(x)}</p></div>`).join(''):'<div class="muted">Not enough current data for analysis yet.</div>'}</div></div>${!dst?`<div class="profile-section"><div class="profile-section-title">Recent player news</div><div class="news-list">${newsHtml}</div></div>`:''}<div class="profile-source">Availability uses fresh Sleeper roster/injury status plus the Fantasy Model's player-week availability factor. Definitive current-week IR/Out/PUP/NFI/suspension status overrides the weekly projection to 0. Recent reports are shown for context and do not independently change the number unless they are reflected in structured availability data.</div></aside></div>`}

function dstProjectionValue''',
'player profile')

# Force fresh Sleeper player metadata on manual league refresh.
s=s.replace("await Promise.all([players(),nflState(),loadSeasonStats(notify)])","await Promise.all([players(notify),nflState(),loadSeasonStats(notify)])",1)

# Show status chips in roster cards/table.
sub1(r"function rosterTable\(r,ids,opt\)\{.*?\}\nfunction picks",
r'''function rosterTable(r,ids,opt){if(!ids.length)return'<div class="empty">No players found.</div>';const rows=ids.map(id=>{const p=st.players?.[id]||{},dst=isDstId(id,p),m=model(id,p),live=n(mi(r.roster_id)?.players_points?.[id],0),slot=opt.get(id),opp=m.opp||'Matchup unavailable',jersey=p.number||p.jersey_number,avgNote=m.avgSource==='actual'?(m.avgGames?`${m.avgGames} GP`:'Actual'):(m.avgSource==='projected'?'Projected':'');return{id,p,dst,m,live,slot,opp,jersey,avgNote,avChip:availabilityChip(m.availability)}});const mobile=`<div class="mobile-player-list">${rows.map(x=>`<button class="mobile-player-card ${x.m.availability?.factor<=0?'player-unavailable':''}" data-player="${esc(x.id)}" data-roster="${r.roster_id}"><div class="mobile-player-top"><img class="mobile-player-image ${x.dst?'dst-logo':''}" src="${assetImage(x.id,x.p)}" alt="" onerror="this.style.visibility='hidden'"><div class="mobile-player-copy"><div class="mobile-player-name">${esc(pname(x.id))}</div><div class="player-meta">${esc(x.p.position||'—')} · ${esc(x.p.team||'FA')}${x.jersey?` · #${esc(x.jersey)}`:''}</div><div class="player-opp">${esc(x.opp)}</div>${x.avChip}</div><div class="mobile-card-action">›</div></div><div class="mobile-player-metrics"><div><span>Week ${st.week}</span><strong>${f(x.m.projection)}</strong></div><div><span>Season PPG</span><strong>${f(x.m.avg)}</strong><small>${esc(x.avgNote)}</small></div><div><span>Dynasty</span><strong>${x.m.dynasty!=null?fi(x.m.dynasty):'—'}</strong></div></div><div class="mobile-player-bottom"><span>${x.slot?`START · ${esc(x.slot)}`:'SIT'}</span><span>Live ${f(x.live)}</span><span>Range ${f(x.m.floor)}–${f(x.m.ceiling)}</span></div><div class="mobile-view-analysis">View news + projection analysis</div></button>`).join('')}</div>`;const desktop=`<div class="roster-table-wrap desktop-roster-table"><table><thead><tr><th>Player</th><th>Projection</th><th>Live Fantasy</th><th>Floor</th><th>Ceiling</th><th>Season PPG</th><th>Dynasty</th><th>Lineup</th><th>Confidence</th></tr></thead><tbody>${rows.map(x=>`<tr class="${x.m.availability?.factor<=0?'player-unavailable-row':''}"><td><div class="player-cell player-open" data-player="${esc(x.id)}" data-roster="${r.roster_id}" role="button" tabindex="0"><img class="player-headshot ${x.dst?'dst-logo':''}" src="${assetImage(x.id,x.p)}" alt="" onerror="this.style.visibility='hidden'"><div><div class="player-name">${esc(pname(x.id))}</div><div class="player-meta">${esc(x.p.position||'—')} · ${esc(x.p.team||'FA')}${x.jersey?` · #${esc(x.jersey)}`:''}</div><div class="player-opp">${esc(x.opp)} · View news + analysis</div>${x.avChip}</div></div></td><td><strong>${f(x.m.projection)}</strong>${x.m.projectionWasOverridden&&x.m.rawProjection!=null?`<div class="cell-sub">Base ${f(x.m.rawProjection)}</div>`:''}</td><td>${f(x.live)}</td><td>${f(x.m.floor)}</td><td>${f(x.m.ceiling)}</td><td><strong>${f(x.m.avg)}</strong>${x.avgNote?`<div class="cell-sub">${esc(x.avgNote)}</div>`:''}</td><td>${x.m.dynasty!=null?fi(x.m.dynasty):'—'}</td><td>${x.slot?`<span class="slot-label">START · ${esc(x.slot)}</span>`:'<span class="slot-label sit">SIT</span>'}</td><td>${esc(conf(x.m.confidence))}</td></tr>`).join('')}</tbody></table></div>`;return mobile+desktop}
function picks''',
'roster table')

# Player-card opening now loads news lazily.
sub1(r"function bind\(\)\{\$\$\('\[data-player\]'\).*?\nasync function init",
"""function bind(){$$('[data-player]').forEach(x=>{x.onclick=()=>openPlayerProfile(x.dataset.player,x.dataset.roster||null);x.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openPlayerProfile(x.dataset.player,x.dataset.roster||null)}}});$('[data-a=\"closeProfile\"]')?.addEventListener('click',()=>{st.profile=null;st.profileRoster=null;render()});$('[data-profile-backdrop]')?.addEventListener('click',e=>{if(e.target===e.currentTarget){st.profile=null;st.profileRoster=null;render()}});$$('[data-route]').forEach(x=>x.onclick=async()=>{st.route=x.dataset.route;localStorage.fm_route=st.route;render();if(st.route==='live'&&!st.games.length)liveLoad();if(st.route==='startsit')players()});$('[data-a=\"nav\"]')?.addEventListener('click',()=>{st.nav=!st.nav;render()});$('[data-a=\"load\"]')?.addEventListener('click',()=>loadLeagues($('#username').value.trim(),+$('#season').value));$$('[data-league]').forEach(x=>x.onclick=()=>openLeague(x.dataset.league));$('[data-a=\"refreshLeague\"]')?.addEventListener('click',()=>refreshLeague(true));$('[data-a=\"back\"]')?.addEventListener('click',()=>{st.league=null;localStorage.removeItem('fm_league_id');render()});$$('[data-tab]').forEach(x=>x.onclick=()=>{st.tab=x.dataset.tab;localStorage.fm_league_tab=st.tab;render()});$('[data-a=\"week\"]')?.addEventListener('change',async e=>{await setWeek(+e.target.value);if(st.route==='live')liveLoad()});$('[data-a=\"team\"]')?.addEventListener('change',e=>{st.team=+e.target.value;render()});$('[data-a=\"tradeA\"]')?.addEventListener('change',e=>{st.tradeA=+e.target.value;st.assetsA=new Set;render()});$('[data-a=\"tradeB\"]')?.addEventListener('change',e=>{st.tradeB=+e.target.value;st.assetsB=new Set;render()});$$('[data-side]').forEach(x=>x.onclick=()=>{const set=x.dataset.side==='a'?st.assetsA:st.assetsB;set.has(x.dataset.asset)?set.delete(x.dataset.asset):set.add(x.dataset.asset);render()});$('[data-a=\"refreshLive\"]')?.addEventListener('click',liveLoad);const search=$('#search');if(search)search.oninput=()=>{const q=search.value.toLowerCase().trim(),found=!q||!st.players?[]:Object.entries(st.players).filter(([,p])=>String(p.full_name||'').toLowerCase().includes(q)&&['QB','RB','WR','TE'].includes(p.position)).slice(0,12),box=$('#results');box.innerHTML=found.map(([id,p])=>`<button class=\"asset\" data-add=\"${id}\"><span><strong>${esc(p.full_name)}</strong><span class=\"muted small\" style=\"display:block\">${esc(p.position)} · ${esc(p.team||'FA')}</span></span><span>+</span></button>`).join('');$$('[data-add]',box).forEach(x=>x.onclick=()=>{if(st.compare.length>=4)return toast('Compare up to four players.');if(!st.compare.includes(x.dataset.add))st.compare.push(x.dataset.add);render()})};$$('[data-remove]').forEach(x=>x.onclick=()=>{st.compare=st.compare.filter(id=>id!==x.dataset.remove);render()})}\nasync function init""",
'bind profile news')

MAIN.write_text(s,encoding='utf-8')

css=CSS.read_text(encoding='utf-8')
css += r'''

/* Web 1.3.2 — fresh availability + player news */
.availability-chip{display:inline-flex;align-items:center;margin-top:5px;padding:3px 7px;border-radius:999px;border:1px solid var(--line);font-size:10px;font-weight:850;color:var(--muted);background:rgba(255,255,255,.025)}.availability-chip.bad{color:var(--bad);border-color:rgba(255,122,133,.34);background:rgba(255,122,133,.09)}.availability-chip.warn{color:var(--warn);border-color:rgba(255,209,102,.32);background:rgba(255,209,102,.08)}.player-unavailable-row{background:linear-gradient(90deg,rgba(255,122,133,.035),transparent 45%)}.mobile-player-card.player-unavailable{border-color:rgba(255,122,133,.28);background:linear-gradient(180deg,rgba(37,22,23,.96),rgba(16,18,16,.98))}.availability-zero{border-color:rgba(255,122,133,.35);background:rgba(255,122,133,.07)}.availability-panel{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:13px;border:1px solid var(--line);border-radius:12px;background:var(--panel2);margin:14px 0}.availability-panel.bad{border-color:rgba(255,122,133,.35);background:rgba(255,122,133,.06)}.availability-panel.warn{border-color:rgba(255,209,102,.3);background:rgba(255,209,102,.05)}.availability-panel span{display:block;color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.06em}.availability-panel strong{display:block;margin-top:3px}.availability-panel p,.availability-panel small{grid-column:1/-1;margin:2px 0 0;color:#dce8df;font-size:12px;line-height:1.45}.availability-panel small{color:var(--muted)}.news-list{display:grid;gap:9px}.news-card{display:block;color:inherit;text-decoration:none;padding:12px;border:1px solid var(--line);border-radius:11px;background:var(--panel2);transition:.15s}.news-card:hover{border-color:rgba(182,255,69,.28);background:rgba(182,255,69,.035)}.news-card strong{display:block;font-size:13px;line-height:1.35}.news-card p{margin:6px 0 0;color:var(--muted);font-size:12px;line-height:1.45}.news-meta{color:var(--accent);font-size:10px;text-transform:uppercase;letter-spacing:.06em;margin-bottom:5px}.news-loading{padding:14px;border:1px dashed var(--line);border-radius:10px;color:var(--muted);font-size:12px}
@media(max-width:600px){.availability-panel{grid-template-columns:1fr}.availability-panel p,.availability-panel small{grid-column:1}}
'''
CSS.write_text(css,encoding='utf-8')

pkg=PKG.read_text(encoding='utf-8')
if '"version": "1.3.1"' not in pkg: raise SystemExit('package version anchor missing')
PKG.write_text(pkg.replace('"version": "1.3.1"','"version": "1.3.2"',1),encoding='utf-8')
